CREATE TABLE categories(id INTEGER PRIMARY KEY CHECK(id>0),name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 80),slug TEXT NOT NULL UNIQUE,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE products(id INTEGER PRIMARY KEY CHECK(id>0),category_id INTEGER NOT NULL REFERENCES categories(id),sku TEXT NOT NULL UNIQUE CHECK(length(sku) BETWEEN 1 AND 64),slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 120),description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 4000),base_price_cents INTEGER NOT NULL CHECK(base_price_cents BETWEEN 1 AND 100000000),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),is_featured INTEGER NOT NULL DEFAULT 0 CHECK(is_featured IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE product_images(id INTEGER PRIMARY KEY CHECK(id>0),product_id INTEGER NOT NULL REFERENCES products(id),asset_path TEXT NOT NULL,alt_text TEXT NOT NULL CHECK(length(alt_text)>0),position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 3),UNIQUE(product_id,position));
CREATE TABLE inventory(product_id INTEGER PRIMARY KEY REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 0 AND 1000000),version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE promotions(id INTEGER PRIMARY KEY CHECK(id>0),product_id INTEGER REFERENCES products(id),category_id INTEGER REFERENCES categories(id),kind TEXT NOT NULL CHECK(kind IN('FINAL_PRICE','PERCENT_BPS')),value INTEGER NOT NULL CHECK(value>0),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,terms TEXT NOT NULL CHECK(length(terms) BETWEEN 1 AND 500),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1,CHECK((product_id IS NOT NULL)+(category_id IS NOT NULL)=1),CHECK((kind='FINAL_PRICE' AND product_id IS NOT NULL) OR (kind='PERCENT_BPS' AND category_id IS NOT NULL AND value<10000)),CHECK(starts_at<ends_at));
CREATE INDEX products_category ON products(category_id,is_active);

CREATE TABLE roles(id INTEGER PRIMARY KEY CHECK(id>0),code TEXT NOT NULL UNIQUE CHECK(code IN('CUSTOMER','ADMIN')));

CREATE TABLE users(id INTEGER PRIMARY KEY CHECK(id>0),role_id INTEGER NOT NULL REFERENCES roles(id),email TEXT NOT NULL UNIQUE CHECK(length(email)<=254 AND email=lower(trim(email))),name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 100),phone TEXT CHECK(phone IS NULL OR length(phone) BETWEEN 7 AND 20),password_hash TEXT NOT NULL,auth_version INTEGER NOT NULL DEFAULT 0 CHECK(auth_version>=0),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY CHECK(id>0),token_hash TEXT NOT NULL UNIQUE,user_id INTEGER REFERENCES users(id),csrf_token TEXT NOT NULL,auth_version INTEGER,namespace TEXT NOT NULL DEFAULT 'imported-source',created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE addresses(id INTEGER PRIMARY KEY CHECK(id>0),user_id INTEGER NOT NULL REFERENCES users(id),recipient TEXT NOT NULL CHECK(length(recipient) BETWEEN 2 AND 100),phone TEXT NOT NULL CHECK(length(phone) BETWEEN 7 AND 20),region TEXT NOT NULL CHECK(length(region) BETWEEN 2 AND 100),province TEXT NOT NULL CHECK(length(province) BETWEEN 2 AND 100),district TEXT NOT NULL CHECK(length(district) BETWEEN 2 AND 100),street TEXT NOT NULL CHECK(length(street) BETWEEN 5 AND 200),reference TEXT CHECK(reference IS NULL OR length(reference)<=200),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);

CREATE TABLE carts(id INTEGER PRIMARY KEY CHECK(id>0),user_id INTEGER UNIQUE REFERENCES users(id),guest_session_id INTEGER UNIQUE REFERENCES sessions(id) ON DELETE CASCADE,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,CHECK((user_id IS NOT NULL)+(guest_session_id IS NOT NULL)=1));
CREATE TABLE cart_items(cart_id INTEGER NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(cart_id,product_id));
CREATE TRIGGER cart_limit BEFORE INSERT ON cart_items WHEN (SELECT COUNT(*) FROM cart_items WHERE cart_id=NEW.cart_id)>=100 BEGIN SELECT RAISE(ABORT,'cart limit'); END;

CREATE TABLE orders(id INTEGER PRIMARY KEY CHECK(id>0),public_id TEXT NOT NULL UNIQUE,creation_nonce TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN('AWAITING_PAYMENT','CONFIRMED','PREPARING','SHIPPED','DELIVERED')),payment_status TEXT NOT NULL CHECK(payment_status IN('REJECTED','APPROVED')),currency TEXT NOT NULL DEFAULT 'PEN' CHECK(currency='PEN'),subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents BETWEEN 1 AND 990000000000),total_cents INTEGER NOT NULL CHECK(total_cents=subtotal_cents),recipient_snapshot TEXT NOT NULL,phone_snapshot TEXT NOT NULL,region_snapshot TEXT NOT NULL,province_snapshot TEXT NOT NULL,district_snapshot TEXT NOT NULL,street_snapshot TEXT NOT NULL,reference_snapshot TEXT,source_cart_id INTEGER REFERENCES carts(id),source_cart_version INTEGER,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE order_items(id INTEGER PRIMARY KEY CHECK(id>0),order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),sku_snapshot TEXT NOT NULL,name_snapshot TEXT NOT NULL,unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents BETWEEN 1 AND 100000000),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),line_total_cents INTEGER NOT NULL CHECK(line_total_cents=unit_price_cents*quantity),promotion_snapshot TEXT,UNIQUE(order_id,product_id));
CREATE TABLE simulated_payments(id INTEGER PRIMARY KEY CHECK(id>0),order_id INTEGER NOT NULL REFERENCES orders(id),outcome TEXT NOT NULL CHECK(outcome IN('APPROVED','REJECTED')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),currency TEXT NOT NULL CHECK(currency='PEN'),created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_approval ON simulated_payments(order_id) WHERE outcome='APPROVED';
CREATE TABLE inventory_movements(id INTEGER PRIMARY KEY CHECK(id>0),product_id INTEGER NOT NULL REFERENCES products(id),order_id INTEGER REFERENCES orders(id),actor_user_id INTEGER REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('SEED','ADJUSTMENT','SALE')),delta INTEGER NOT NULL,quantity_after INTEGER NOT NULL CHECK(quantity_after BETWEEN 0 AND 1000000),reason TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(kind!='SALE' OR (delta<0 AND order_id IS NOT NULL)));
CREATE UNIQUE INDEX one_sale ON inventory_movements(order_id,product_id) WHERE kind='SALE';
CREATE TABLE order_status_history(id INTEGER PRIMARY KEY CHECK(id>0),order_id INTEGER NOT NULL REFERENCES orders(id),from_status TEXT,to_status TEXT NOT NULL,actor_user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE idempotency_records(id INTEGER PRIMARY KEY CHECK(id>0),user_id INTEGER NOT NULL REFERENCES users(id),operation TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response_status INTEGER NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,operation,key));
CREATE INDEX orders_customer ON orders(user_id,created_at);
CREATE INDEX payments_order ON simulated_payments(order_id,created_at);
CREATE INDEX history_order ON order_status_history(order_id,created_at);

CREATE TABLE schema_migrations(version TEXT PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TRIGGER payment_amount BEFORE INSERT ON simulated_payments WHEN NEW.amount_cents!=(SELECT total_cents FROM orders WHERE id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'payment total mismatch'); END;
